"""What a module generated by the Python backend needs at run time (shipped, next to the
modules, as `j2jme_runtime.py`, followed by the built-in functions of `compiler/builtins.py`).

It imports nothing of the engine: the host project runs the generated modules with its own
interpreter. The rules it keeps are the engine's, not Python's:

- a path through the input (`root.a.b[0].c`) yields null where anything on the way is missing,
  never an error;
- arithmetic on a null is null; an ordering comparison with a null is false (as in SQL);
- a rule that fails leaves its field out and is reported once, under its name; the others go on;
- a bare `return` leaves the field out, `return Null` (or a value that is null) puts a null.
"""

from __future__ import annotations

import contextvars
import json
import operator
from concurrent.futures import ThreadPoolExecutor
from typing import Any


class _Omit:
    """What a rule gives when it contributes nothing: the field is left out."""

    def __repr__(self) -> str:
        return "OMIT"

    def __bool__(self) -> bool:
        return False


OMIT = _Omit()

_errors: contextvars.ContextVar[dict[str, str] | None] = contextvars.ContextVar(
    "j2jme_errors", default=None
)


class MappingError(Exception):
    """The mapping ran, but rules failed: `errors` is `[{"rule", "cause"}, ...]`."""

    def __init__(self, mapping_id: str, errors: list[dict[str, str]]):
        self.mapping_id = mapping_id
        self.errors = errors
        super().__init__(
            json.dumps({"mapping": mapping_id, "total_errors": len(errors), "errors": errors})
        )


class MissingImplementation(Exception):
    """A function the project declares has no code for Python: the rule that calls it did not run."""


def _rule(name: str, function: Any, *args: Any) -> Any:
    """Calls a rule function; a failure is recorded (the first one of the rule) and the rule
    gives OMIT."""
    try:
        return function(*args)
    except Exception as exc:  # noqa: BLE001 - any failure of a rule is that rule's
        errors = _errors.get()
        if errors is not None and name not in errors:
            errors[name] = f"{type(exc).__name__}: {exc}"
        return OMIT


def _pmap(target: list[Any], name: str, function: Any, degree: int, calls: list[tuple]) -> None:
    """What a loop does with a `@parallel` element rule: the rule is called for each element in up
    to `degree` threads, and what it gives is appended to `target` in element order. Each call
    keeps its own errors, merged in element order afterwards, so the first failure of a rule is
    the first element's and the result is the sequential one's, whatever the threads' timing."""

    def one(args: tuple) -> tuple[Any, dict[str, str]]:
        errors: dict[str, str] = {}
        token = _errors.set(errors)
        try:
            return _rule(name, function, *args), errors
        finally:
            _errors.reset(token)

    if degree > 1 and len(calls) > 1:
        with ThreadPoolExecutor(max_workers=degree) as pool:
            results = list(pool.map(one, calls))
    else:
        results = [one(args) for args in calls]
    outer = _errors.get()
    for value, errors in results:
        _append(target, value)
        if outer is not None:
            for rule, cause in errors.items():
                outer.setdefault(rule, cause)


def _get(value: Any, *path: Any) -> Any:
    """`value` followed along `path` (names and positions); null as soon as a step is missing."""
    for step in path:
        if value is None:
            return None
        if isinstance(step, int):
            if isinstance(value, list) and -len(value) <= step < len(value):
                value = value[step]
            else:
                return None
        else:
            value = value.get(step) if isinstance(value, dict) else None
    return value


def _each(value: Any) -> Any:
    """What a `for` runs over: the elements of an array; nothing for a missing one."""
    if value is None:
        return []
    if isinstance(value, list):
        return value
    raise TypeError(f"cannot iterate over {type(value).__name__}")


def _record(**fields: Any) -> dict[str, Any]:
    """An object of the output: the fields that were left out are not in it."""
    return {k: v for k, v in fields.items() if v is not OMIT}


def _append(target: list[Any], value: Any) -> None:
    if value is not OMIT:
        target.append(value)


class _Out:
    """The output being built: `out.F = v` sets a field (not when v is OMIT), and reading a name
    that is not set yet gives the array to append to."""

    def __init__(self) -> None:
        object.__setattr__(self, "_fields", {})

    def __setattr__(self, name: str, value: Any) -> None:
        if value is not OMIT:
            self._fields[name] = value

    def __getattr__(self, name: str) -> Any:
        return self._fields.setdefault(name, [])


def _arith(op: Any):
    def apply(a: Any, b: Any) -> Any:
        return None if a is None or b is None else op(a, b)

    return apply


_add = _arith(operator.add)
_sub = _arith(operator.sub)
_mul = _arith(operator.mul)
_div = _arith(operator.truediv)
_floordiv = _arith(operator.floordiv)
_mod = _arith(operator.mod)


def _neg(a: Any) -> Any:
    return None if a is None else -a


def _order(op: Any):
    def compare(a: Any, b: Any) -> bool:
        return False if a is None or b is None else op(a, b)

    return compare


_lt = _order(operator.lt)
_le = _order(operator.le)
_gt = _order(operator.gt)
_ge = _order(operator.ge)


def _plain(value: Any) -> Any:
    """The output as JSON: a number that is whole is written as an integer (5, not 5.0)."""
    if isinstance(value, float) and value.is_integer():
        return int(value)
    if isinstance(value, dict):
        return {k: _plain(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_plain(v) for v in value]
    return value


def _execute(
    mapping_id: str, run: Any, source: Any, raising: bool
) -> tuple[Any, list[dict[str, str]]]:
    """Runs a mapping on `source` (JSON text, or the parsed document). Gives the output and
    the rule errors; with `raising`, a MappingError instead when there are errors."""
    document = json.loads(source) if isinstance(source, str | bytes | bytearray) else source
    errors: dict[str, str] = {}
    token = _errors.set(errors)
    out = _Out()
    try:
        run(document, out)
    except Exception as exc:  # noqa: BLE001 - outside any rule: reported as the mapping's own
        errors.setdefault("<mapping>", f"{type(exc).__name__}: {exc}")
    finally:
        _errors.reset(token)
    report = [{"rule": rule, "cause": cause} for rule, cause in errors.items()]
    if raising and report:
        raise MappingError(mapping_id, report)
    return _plain(out._fields), report
